<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ArrowLeft,Plus,Send,Square,AtSign,Settings2,Check,Undo2,GitBranch,Sparkles,History} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {slotModel} from '../repositories/local-models'
import {emptyAgentSession,agentReadableKinds,agentLabel,agentEditableFields,type AgentSession,type AgentRun,type AgentChange} from './contract'
import {createAgentRun,startAgentRun,planAgentRun,decideAgentChange,rollbackAgentChange,stopAgentRun,recoverAgentRuns} from './runtime'
import TeamPanel from './TeamPanel.vue'
import Sheet from '../components/Sheet.vue'
const store=useLocal(),route=useRoute(),sessions=ref<Document<AgentSession>[]>([]),current=ref<Document<AgentSession>|null>(null),runs=ref<Document<AgentRun>[]>([]),changes=ref<Document<AgentChange>[]>([]),references=ref<Document[]>([]),query=ref(''),draft=ref(''),error=ref(''),busy=ref(false),pick=ref(false),options=ref(false),advanced=ref(false),manualPlan=ref(''),modelLabel=ref('配置文本模型'),archives=ref(false),history=ref(false),draftCopies=ref<Document<{agentSessionId:string;text:string;conflict:boolean;createdAt:string}>[]>([])
const visible=computed(()=>sessions.value.filter(row=>row.value.archived===archives.value&&row.value.title.toLowerCase().includes(query.value.toLowerCase()))),config=ref<AgentSession>(emptyAgentSession()),selectedRefs=ref<string[]>([])
const labels:Record<string,string>={queued:'等待开始',planning:'正在规划',streaming:'正在接收计划',ready:'待继续',running:'执行中',needs_approval:'等待确认',completed:'已完成',cancelled:'已停止',failed:'未完成',unknown:'响应未确认'}
let disposed=false,selectGeneration=0,hydrating=false,poll:ReturnType<typeof setInterval>|null=null,draftTimer:ReturnType<typeof setTimeout>|null=null,draftRevision=0,draftWork=Promise.resolve();const control=new AbortController(),draftStates=new Map<string,{revision:number;text:string;conflictId:string;conflictRevision:number}>()
async function load(){const vault=store.vault;if(!vault)return;const rows=(await vault.list<AgentSession>('settings')).filter(row=>row.value.assetType==='agent-session').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));if(disposed||store.vault!==vault)return;sessions.value=rows;if(!current.value&&typeof route.query.session==='string'){const wanted=rows.find(row=>row.id===route.query.session);if(!wanted)throw Error('这个助手会话已删除或无法打开');archives.value=wanted.value.archived;await select(wanted)}else if(!current.value&&rows[0])await select(rows[0]);else if(current.value){const updated=rows.find(row=>row.id===current.value!.id);if(updated)current.value=updated;await refresh()}try{const profile=await slotModel(vault,'text');modelLabel.value=profile.value.name+' · '+profile.value.modelId}catch{modelLabel.value='配置文本模型'}}
async function select(row:Document<AgentSession>){const generation=++selectGeneration;if(draftTimer)clearTimeout(draftTimer);await saveDraft();if(disposed||generation!==selectGeneration)return;hydrating=true;try{current.value=row;draft.value='';draftRevision=0;const vault=store.vault;if(!vault)return;const saved=await vault.read<{agentSessionId:string;text:string}>('agent-draft:'+row.id);if(disposed||current.value?.id!==row.id||generation!==selectGeneration||store.vault!==vault)return;if(saved){draft.value=saved.value.text;draftRevision=saved.revision}draftStates.set(row.id,{revision:draftRevision,text:draft.value,conflictId:'agent-draft-conflict:'+row.id+':'+crypto.randomUUID(),conflictRevision:0});await refresh()}finally{if(generation===selectGeneration)hydrating=false}}
async function refresh(){const vault=store.vault,id=current.value?.id;if(!vault||!id)return;await recoverAgentRuns(vault);const session=await vault.read<AgentSession>(id),rows=await vault.readMany<AgentRun>(session?.value.runIds||[]),diffs=(await vault.list<AgentChange>('changeSet')).filter(row=>row.value.sessionId===id),refs=await vault.readMany(session?.value.referenceIds||[]),copies=(await vault.list<{agentSessionId:string;text:string;conflict:boolean;createdAt:string}>('settings')).filter(row=>row.value.conflict===true&&row.value.agentSessionId===id);if(disposed||current.value?.id!==id||store.vault!==vault)return;if(session)current.value=session;runs.value=rows;changes.value=diffs;if(!pick.value)references.value=refs;draftCopies.value=copies}
async function saveDraft(){const vault=store.vault,id=current.value?.id,text=draft.value;if(!vault||!id)return;const state=draftStates.get(id)||{revision:draftRevision,text:'',conflictId:'agent-draft-conflict:'+id+':'+crypto.randomUUID(),conflictRevision:0};draftStates.set(id,state);draftWork=draftWork.catch(()=>{}).then(async()=>{if(!vault.unlocked||state.text===text)return;const operation=crypto.randomUUID(),expected=state.revision,value={agentSessionId:id,text};try{await vault.commitBundle(operation,[{kind:'settings',id:'agent-draft:'+id,expectedRevision:expected,value}]);state.revision=expected+1;state.text=text}catch(e){const receipt=vault.unlocked?await vault.receipt(operation):null,saved=receipt?await vault.read('agent-draft:'+id):null;if(saved&&saved.revision===expected+1&&canonical(saved.value)===canonical(value)){state.revision=expected+1;state.text=text;return}if((e as {code?:string}).code!=='REVISION_CONFLICT')throw e;const copy={agentSessionId:id,text,conflict:true,createdAt:new Date().toISOString()},copyOperation=crypto.randomUUID();try{await vault.commitBundle(copyOperation,[{kind:'settings',id:state.conflictId,expectedRevision:state.conflictRevision,value:copy}])}catch(error){const done=vault.unlocked?await vault.receipt(copyOperation):null;if(!done)throw error}state.conflictRevision++;state.text=text;if(!disposed&&current.value?.id===id){error.value='另一份草稿也已保存，可在另存草稿中选用';await refresh()}}}).catch(e=>{if(!disposed&&current.value?.id===id)error.value=(e as Error).message});await draftWork}
async function useDraftCopy(copy:Document<{text:string}>){const vault=store.vault,id=current.value?.id;if(!vault||!id)return;const row=await vault.read<{text:string}>('agent-draft:'+id),state=draftStates.get(id);if(disposed||current.value?.id!==id||store.vault!==vault)return;if(state){state.revision=row?.revision||0;state.text=row?.value.text||''}draft.value=copy.value.text;await saveDraft()}

watch(draft,()=>{if(hydrating)return;if(draftTimer)clearTimeout(draftTimer);void saveDraft()},{flush:'sync'})
async function newSession(fork=false){const vault=store.vault;if(!vault)return;try{const id='agent-session:'+crypto.randomUUID(),value=fork&&current.value?{...current.value.value,title:current.value.value.title+' · 分叉',runIds:[],mode:'confirm' as const,grants:[],createdAt:new Date().toISOString(),parentId:current.value.id}:emptyAgentSession();await vault.commit(crypto.randomUUID(),'settings',id,0,value);await load();await select((await vault.read<AgentSession>(id))!)}catch(e){error.value=(e as Error).message}}
async function pickReferences(){const vault=store.vault;if(!vault||!current.value)return;try{const kinds=agentReadableKinds.filter(kind=>!['paragraph','message','memory'].includes(kind)),rows=(await Promise.all(kinds.map(kind=>vault.list(kind)))).flat();if(disposed)return;references.value=rows;selectedRefs.value=[...current.value.value.referenceIds];pick.value=true}catch(e){error.value=(e as Error).message}}
async function saveRefs(){const vault=store.vault,row=current.value;if(!vault||!row)return;try{if(selectedRefs.value.length>32)throw new Error('最多选择 32 个引用');await vault.commit(crypto.randomUUID(),'settings',row.id,row.revision,{...row.value,referenceIds:[...selectedRefs.value],grants:row.value.grants.filter(grant=>selectedRefs.value.includes(grant.targetId))});pick.value=false;await load()}catch(e){error.value=(e as Error).message}}
function openOptions(){if(!current.value)return;config.value=JSON.parse(canonical(current.value.value));options.value=true}
async function saveOptions(){const vault=store.vault,row=current.value;if(!vault||!row)return;try{await vault.commit(crypto.randomUUID(),'settings',row.id,row.revision,config.value);options.value=false;await load()}catch(e){error.value=(e as Error).message}}
function grant(id:string,enabled:boolean){config.value.grants=config.value.grants.filter(grant=>grant.targetId!==id);if(enabled)config.value.grants.push({targetId:id,tools:['edit','write','replace']})}
async function submit(){const vault=store.vault,row=current.value,text=draft.value.trim();if(!vault||!row||!text||busy.value)return;busy.value=true;error.value='';try{const run=await createAgentRun(vault,row.id,text,advanced.value?JSON.parse(manualPlan.value):undefined,control.signal);if(disposed)return;draft.value='';await saveDraft();await load();const work=advanced.value?startAgentRun(vault,run.id):planAgentRun(vault,run.id);void work.catch(e=>{if(!disposed)error.value=(e as Error).message}).finally(()=>{if(!disposed)void refresh()})}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function decide(change:Document<AgentChange>,accept:boolean){const vault=store.vault;if(!vault)return;try{await decideAgentChange(vault,change.id,accept);await refresh();void startAgentRun(vault,change.value.runId).catch(e=>{if(!disposed)error.value=(e as Error).message})}catch(e){error.value=(e as Error).message}}
async function rollback(change:Document<AgentChange>){if(!store.vault)return;try{await rollbackAgentChange(store.vault,change.id);await refresh()}catch(e){error.value=(e as Error).message}}
async function stop(run:Document<AgentRun>){if(!store.vault)return;try{await stopAgentRun(store.vault,run.id);await refresh()}catch(e){error.value=(e as Error).message}}
async function resume(run:Document<AgentRun>){if(!store.vault)return;try{await startAgentRun(store.vault,run.id);await refresh()}catch(e){error.value=(e as Error).message}}
const diffFields=(change:AgentChange)=>Object.keys(change.after).filter(field=>canonical(change.before[field]??null)!==canonical(change.after[field]??null))
onMounted(async()=>{try{await load();const ref=route.query.ref;if(typeof ref==='string'&&store.vault){const source=await store.vault.read(ref);if(source&&agentReadableKinds.includes(source.kind)&&!(source.kind==='message'&&(source.value as {hidden?:boolean}).hidden)){await newSession();const row=current.value!;await store.vault.commit(crypto.randomUUID(),'settings',row.id,row.revision,{...row.value,referenceIds:[ref]});await load()}}}catch(e){error.value=(e as Error).message}poll=setInterval(()=>void refresh().catch(e=>{if(!disposed)error.value=(e as Error).message}),1000)})
onUnmounted(()=>{void saveDraft();disposed=true;control.abort();if(poll)clearInterval(poll);if(draftTimer)clearTimeout(draftTimer)})
</script>
<template><section class="final-agent"><aside class="final-agent-sessions"><RouterLink to="/local/library" class="final-text-link"><ArrowLeft :size="18"/>书架</RouterLink><div class="final-section-title"><h2>创作助手</h2><button class="final-icon-button" aria-label="新建助手会话" @click="newSession()"><Plus :size="20"/></button></div><input v-model="query" aria-label="搜索助手会话" placeholder="搜索会话"><label class="final-check"><input v-model="archives" type="checkbox">已归档</label><button v-for="row in visible" :key="row.id" :aria-current="current?.id===row.id?'page':undefined" @click="select(row)">{{row.value.title}}<small>{{row.value.runIds.length}} 个任务</small></button></aside><div class="final-agent-workspace"><header class="final-agent-header"><RouterLink to="/local/library" class="final-icon-button" aria-label="返回书架"><ArrowLeft :size="20"/></RouterLink><div><h1>{{current?.value.title||'创作助手'}}</h1><RouterLink class="final-subtle" to="/local/settings/models">{{modelLabel}}</RouterLink></div><div class="final-page-actions"><button class="final-icon-button" aria-label="助手会话列表" @click="history=true"><History :size="20"/></button><button class="final-icon-button" aria-label="新建创作会话" @click="newSession()"><Plus :size="20"/></button><button :disabled="!current" class="final-icon-button" aria-label="分叉助手会话" @click="newSession(true)"><GitBranch :size="20"/></button><button :disabled="!current" class="final-icon-button" aria-label="助手设置" @click="openOptions"><Settings2 :size="20"/></button></div></header><div class="final-agent-results"><p v-if="error" class="final-error" role="alert">{{error}}</p><div v-if="!current" class="final-empty"><Sparkles :size="34"/><h2>让想法成为故事</h2><button class="final-primary" @click="newSession()">新建创作</button></div><div v-else-if="!runs.length" class="final-empty"><Sparkles :size="34"/><h2>从一个想法开始</h2><button @click="pickReferences"><AtSign :size="18"/>引用故事或角色</button></div><article v-for="run in runs.filter(row=>!row.value.delegation)" :key="run.id" class="final-agent-run"><div class="final-section-title"><strong>{{run.value.instruction}}</strong><small role="status">{{labels[run.value.status]}}</small></div><small class="final-subtle">{{run.value.cursor}} / {{run.value.plan.length}} 步 · {{run.value.provider?1:0}} 次模型请求</small><p v-if="run.value.error" class="final-error">{{run.value.error}}</p><details v-if="run.value.provider?.output"><summary>模型返回的计划</summary><pre>{{run.value.provider.output}}</pre></details><div v-for="result in run.value.results" :key="result.callId" class="final-agent-tool"><Check :size="18"/><div><strong>{{result.tool}} · {{result.summary}}</strong><details><summary>工具结果</summary><pre>{{result.data}}</pre></details></div></div><article v-for="change in changes.filter(row=>row.value.runId===run.id)" :key="change.id" class="final-agent-change"><strong>{{change.value.tool}} · 版本 {{change.value.expectedRevision}} → {{change.value.expectedRevision+1}}</strong><div v-for="field in diffFields(change.value)" :key="field"><small>{{field}}</small><div class="final-agent-diff"><pre class="is-before">{{typeof change.value.before[field]==='string'?change.value.before[field]:JSON.stringify(change.value.before[field],null,2)}}</pre><pre class="is-after">{{typeof change.value.after[field]==='string'?change.value.after[field]:JSON.stringify(change.value.after[field],null,2)}}</pre></div></div><div class="final-grid-actions"><template v-if="change.value.status==='proposed'&&run.value.status==='needs_approval'"><button @click="decide(change,false)">拒绝</button><button class="final-primary" @click="decide(change,true)">确认修改</button></template><button v-if="change.value.status==='applied'" @click="rollback(change)"><Undo2 :size="16"/>回滚</button><small>{{({proposed:'待确认',applied:'已保存',rejected:'已拒绝',rolled_back:'已回滚'})[change.value.status]}}</small></div></article><TeamPanel :parent="run"/><button v-if="['ready','running','planning','streaming','queued','needs_approval'].includes(run.value.status)" @click="stop(run)"><Square :size="16"/>停止任务</button><button v-if="['ready','running'].includes(run.value.status)" @click="resume(run)">继续原计划</button></article></div><footer v-if="current" class="final-agent-composer"><details v-if="draftCopies.length" class="final-draft-copies"><summary>另存的草稿 · {{draftCopies.length}}</summary><article v-for="copy in draftCopies" :key="copy.id"><p>{{copy.value.text}}</p><button @click="useDraftCopy(copy)">使用这份草稿</button></article></details><div class="final-grid-actions"><button @click="pickReferences"><AtSign :size="18"/>引用 {{current.value.referenceIds.length||''}}</button><small>{{({read:'只读',confirm:'逐次确认',auto:'按授权自动'})[current.value.mode]}}</small></div><form @submit.prevent="submit"><textarea v-model="draft" aria-label="助手任务" maxlength="20000" rows="2" placeholder="帮我整理这段故事…" :disabled="busy||current.value.archived"></textarea><button class="final-primary" aria-label="运行助手任务" :disabled="busy||!draft.trim()||current.value.archived"><Send :size="20"/></button></form><RouterLink class="final-text-link" to="/local/agent/skills">技能工坊</RouterLink><details><summary>工具计划</summary><label class="final-check"><input v-model="advanced" type="checkbox">直接运行注册工具</label><textarea v-if="advanced" v-model="manualPlan" aria-label="助手工具计划" class="final-code-input" placeholder='[{"tool":"read","arguments":{"id":"选中的引用ID"}}]' maxlength="100000"></textarea></details></footer></div><Sheet v-if="history" title="助手会话" @close="history=false"><input v-model="query" aria-label="搜索已有助手会话" placeholder="搜索会话"><label class="final-check"><input v-model="archives" type="checkbox">已归档</label><div class="final-agent-reference-list"><button v-for="row in visible" :key="row.id" @click="select(row);history=false">{{row.value.title}}</button></div></Sheet><Sheet v-if="pick" title="选择引用" @close="pick=false"><div class="final-agent-reference-list"><label v-for="row in references" :key="row.id" class="final-check"><input v-model="selectedRefs" type="checkbox" :value="row.id"><span>{{agentLabel(row)}}<small>{{row.kind}} · v{{row.revision}}</small></span></label></div><button class="final-primary" @click="saveRefs">保存引用</button></Sheet><Sheet v-if="options" title="助手设置" @close="options=false"><form class="final-card-form" @submit.prevent="saveOptions"><label>会话名称<input v-model="config.title" maxlength="200" required></label><label>助手人格<textarea v-model="config.persona" maxlength="12000"></textarea></label><label>修改审批<select v-model="config.mode" aria-label="助手审批模式"><option value="read">只读</option><option value="confirm">每次确认</option><option value="auto">仅已授权工具自动执行</option></select></label><fieldset v-if="config.mode==='auto'"><legend>持续允许修改</legend><label v-for="id in config.referenceIds" :key="id" class="final-check"><input type="checkbox" :checked="config.grants.some(grant=>grant.targetId===id)" @change="grant(id,($event.target as HTMLInputElement).checked)">{{references.find(row=>row.id===id)?agentLabel(references.find(row=>row.id===id)!):id}}</label></fieldset><label>步骤上限<input v-model.number="config.limits.steps" type="number" min="1" max="64"></label><label>模型调用上限<input v-model.number="config.limits.calls" type="number" min="1" max="8"></label><label>并发上限<input v-model.number="config.limits.parallel" type="number" min="1" max="3"></label><label class="final-check"><input v-model="config.recordPrompt" type="checkbox">保存模型请求正文</label><label class="final-check"><input v-model="config.archived" type="checkbox">归档会话</label><button class="final-primary">保存助手设置</button></form></Sheet></section></template>
<style scoped>
.final-agent{height:100dvh;display:grid;grid-template-columns:260px minmax(0,1fr);background:var(--paper)}.final-agent-sessions{padding:24px 20px;background:var(--canvas);border-right:1px solid var(--edge);overflow:auto;display:flex;flex-direction:column;gap:12px}.final-agent-sessions .final-section-title{margin:12px 0}.final-agent-sessions>button{text-align:left;display:grid;gap:4px}.final-agent-sessions>button[aria-current]{background:var(--wash);border-color:var(--accent)}.final-agent-sessions small{color:var(--quiet)}.final-agent-workspace{min-width:0;display:flex;flex-direction:column;overflow:hidden}.final-agent-header{display:flex;justify-content:space-between;padding:20px 32px;border-bottom:1px solid var(--edge);background:var(--canvas)}.final-agent-header h1{font-size:24px}.final-agent-results{flex:1;overflow-y:auto;padding:32px max(24px,calc((100vw - 1180px)/2))}.final-agent-run{padding:24px;background:var(--canvas);border:1px solid var(--edge);border-radius:16px;margin-bottom:24px;display:grid;gap:16px}.final-agent-run .final-section-title{margin:0;align-items:start;gap:16px}.final-agent-run pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;max-height:400px;overflow:auto}.final-agent-tool{display:flex;gap:12px;align-items:start;padding:16px;background:var(--paper);border-radius:12px}.final-agent-tool>div{min-width:0;flex:1}.final-agent-tool>svg{color:var(--good);flex-shrink:0;margin-top:4px}.final-agent-change{display:grid;gap:16px;padding:20px;border:1px solid var(--edge);border-radius:12px}.final-agent-diff{display:grid;grid-template-columns:1fr 1fr;gap:12px}.final-agent-diff pre{padding:16px;border-radius:8px;border:1px solid var(--edge)}.is-before{background:color-mix(in srgb,var(--danger) 7%,var(--canvas))}.is-after{background:color-mix(in srgb,var(--good) 8%,var(--canvas))}.final-agent-composer{border-top:1px solid var(--edge);padding:16px 24px;background:var(--canvas)}.final-agent-composer form{display:flex;gap:12px;align-items:end;margin-top:12px}.final-agent-composer textarea{resize:vertical;max-height:220px}.final-agent-composer summary{font-size:13px;color:var(--quiet);margin-top:12px}.final-agent-reference-list{display:grid;gap:12px;margin-bottom:24px}.final-agent-reference-list small{display:block;color:var(--quiet)}@media(max-width:767px){.final-agent{grid-template-columns:1fr}.final-agent-sessions{display:none}.final-agent-header{padding:16px}.final-agent-results{padding:20px 16px}.final-agent-run{padding:20px}.final-agent-composer{padding:12px 16px calc(12px + env(safe-area-inset-bottom))}.final-agent-diff{grid-template-columns:1fr}.final-agent-header{gap:8px}.final-agent-header>div:first-of-type{min-width:0;flex:1}.final-agent-header h1{font-size:21px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.final-agent-header .final-page-actions{gap:4px}.final-agent-header .final-page-actions button:nth-child(3){display:none}.final-agent-header .final-subtle{font-size:11px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
</style>
